contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address a, address b, uint256 v, uint256 supply) public {
        require(a != address(0) && b != address(0));
        c = address(new C(supply, "t", "s")) == address(0) ? c : c;
        require(v > 0 && v <= supply);
        require(a != b);
        bool reverted;
        try c.transfer(b, v) { reverted = false; }
        catch { reverted = true; }
        assert(reverted || (c.balanceOf(b) == v && c.totalSupply() == supply));
    }
    receive() external payable {}
}

