contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 v) public {
        require(v > 0);
        uint256 balBefore = c.balanceOf(address(this));
        bool reverted;
        if (v > balBefore) {
            try c.transfer(address(this), v) returns (bool) { reverted = false; }
            catch { reverted = true; }
            assert(reverted);
        } else {
            uint256 supplyBefore = c.totalSupply();
            bool ok = c.transfer(address(0xDead), v);
            assert(ok && c.balanceOf(address(this)) == balBefore - v && c.totalSupply() == supplyBefore);
        }
    }
    receive() external payable {}
}

