contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, uint256 value) public {
        require(!c.frozenAccount(from));
        uint256 fromBefore = c.balanceOf(from);
        uint256 supplyBefore = c.totalSupply();
        bool reverted;
        if (from == address(this)) {
            try c.transfer(address(0), value) { reverted = false; }
            catch { reverted = true; }
        } else {
            reverted = true; // zero-address transfers from this contract's sender are checked below
        }
        if (from != address(this)) {
            // sender is always this contract; check directly
            try c.transfer(address(0), value) { reverted = false; }
            catch { reverted = true; }
        }
        assert(reverted && c.balanceOf(address(this)) == fromBefore && c.totalSupply() == supplyBefore);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address to, uint256 value) public {
        require(to != address(0));
        require(!c.frozenAccount(address(this)));
        require(!c.frozenAccount(to));
        uint256 senderBefore = c.balanceOf(address(this));
        uint256 toBefore = c.balanceOf(to);
        uint256 supplyBefore = c.totalSupply();
        require(value > senderBefore);
        bool reverted;
        try c.transfer(to, value) { reverted = false; }
        catch { reverted = true; }
        assert(
            reverted
            && c.balanceOf(address(this)) == senderBefore
            && c.balanceOf(to) == toBefore
            && c.totalSupply() == supplyBefore
        );
    }
    receive() external payable {}
}
